    "Campaign": "Campagna",
    "© 2026 SAYAND. All rights reserved.": "© 2026 SAYAND. Tutti i diritti riservati.",
    "We don't do fashion that makes you choose between who you are and who the world wants you to be. We started this brand to fix a gap we saw everywhere: the space between classic elegance and native authenticity. Too often, modesty was treated as an afterthought. Culture was diluted. Quality was gatekept by price tags. We decided to change that. This is where Nigerian heritage meets global style. We design and curate for everyone who moves through the world with quiet confidence — men, women, and anyone who believes that what you wear should reflect your values. Our pieces span the full spectrum: sharp formalwear, elevated streetwear, timeless classics, and statement accessories that carry the weight of craftsmanship. Everything we make is built to last. Handwoven textiles. Ethically sourced materials. Local production. Top-tier quality at prices that don't require a second thought. We work directly with artisans because we believe the best fashion is human-made, not factory-churned. We're an online store now, shipping globally, with a physical space on the horizon. But no matter how we grow, our promise stays the same: we style you with modesty. Not as a limitation — as a standard. Rooted in culture. Crafted with purpose. Worn with pride.": "Non creiamo una moda che ti costringa a scegliere tra chi sei e chi il mondo vorrebbe che fossi.\nAbbiamo fondato questo marchio per colmare una distanza che vedevamo ovunque: quella tra eleganza classica e autenticità delle proprie radici. Troppo spesso, la sobrietà veniva messa in secondo piano. La cultura perdeva la sua identità. La qualità era riservata a chi poteva permettersi prezzi elevati. Abbiamo deciso di cambiare le cose.\nQui, il patrimonio culturale nigeriano incontra lo stile globale. Creiamo e selezioniamo capi per chi affronta il mondo con una sicurezza discreta: uomini, donne e chiunque creda che ciò che indossa debba rispecchiare i propri valori. Le nostre proposte spaziano dall'abbigliamento formale impeccabile allo streetwear ricercato, dai classici intramontabili agli accessori di carattere che esprimono il valore della maestria artigianale.\nTutto ciò che realizziamo è pensato per durare. Tessuti lavorati a mano. Materiali di provenienza etica. Produzione locale. Qualità eccellente a prezzi accessibili. Collaboriamo direttamente con gli artigiani perché crediamo che la moda migliore nasca dalle mani delle persone, non dalla produzione industriale in serie.\nOggi siamo un negozio online con spedizioni in tutto il mondo e uno spazio fisico all'orizzonte. Ma, qualunque sia la nostra crescita, la promessa resta la stessa: vestire il tuo stile con sobrietà. Non come un limite, ma come un principio.\nRadicati nella cultura. Creati con uno scopo. Indossati con orgoglio.",
    "Join the SAYAND team. We are always looking for passionate individuals who share our vision for modern, minimalist fashion.": "Entra nel team SAYAND. Siamo sempre alla ricerca di persone appassionate che condividano la nostra visione di una moda moderna e minimalista.",
    "CURRENT OPENINGS": "POSIZIONI APERTE",
