    "Delivery within Italy: 3–7 days.": "Consegna in Italia: 3–7 giorni.",
    "International delivery: 5–14 days.": "Consegna internazionale: 5–14 giorni.",
    "Shipping charges are shown at checkout.": "Le spese di spedizione sono indicate al checkout.",
    "Open product": "Apri prodotto",
    "Delivery within Italy: 3–7 days. International delivery: 5–14 days.": "Consegna in Italia: 3–7 giorni. Consegna internazionale: 5–14 giorni.",
    "Delivery within Italy: 3–7 days. International delivery: 5–14 days. Free returns within 30 days of purchase.": "Consegna in Italia: 3–7 giorni. Consegna internazionale: 5–14 giorni. Resi gratuiti entro 30 giorni dall'acquisto.",
    "Delivery within Italy: 3–7 days. International delivery: 5–14 days. Free returns within 30 days of purchase. Items must be in original condition with tags attached.": "Consegna in Italia: 3–7 giorni. Consegna internazionale: 5–14 giorni. Resi gratuiti entro 30 giorni dall'acquisto. Gli articoli devono essere nelle condizioni originali, con i cartellini attaccati.",
    "Shipping Info | SAYAND": "INFORMAZIONI SULLA SPEDIZIONE | SAYAND",
    "We couldn't create a reset link. Check your email address and use the one you registered with. If you haven't registered, choose Sign up below.": "Non è stato possibile creare un link per reimpostare la password. Controlla l'indirizzo email e usa quello con cui ti sei registrato. Se non ti sei ancora registrato, scegli Registrati qui sotto.",
    "Please enter a valid email address, for example name@example.com.": "Inserisci un indirizzo email valido, ad esempio nome@esempio.com.",
    "Delivery within Italy: 3–7 working days.": "Consegna in Italia: 3–7 giorni lavorativi.",
    "International delivery: 5–14 working days.": "Consegna internazionale: 5–14 giorni lavorativi.",
    "Delivery within Italy: 3–7 working days. International delivery: 5–14 working days.": "Consegna in Italia: 3–7 giorni lavorativi. Consegna internazionale: 5–14 giorni lavorativi.",
    "Delivery within Italy: 3–7 working days. International delivery: 5–14 working days. Free returns within 30 days of purchase.": "Consegna in Italia: 3–7 giorni lavorativi. Consegna internazionale: 5–14 giorni lavorativi. Resi gratuiti entro 30 giorni dall'acquisto.",
    "Delivery within Italy: 3–7 working days. International delivery: 5–14 working days. Free returns within 30 days of purchase. Items must be in original condition with tags attached.": "Consegna in Italia: 3–7 giorni lavorativi. Consegna internazionale: 5–14 giorni lavorativi. Resi gratuiti entro 30 giorni dall'acquisto. Gli articoli devono essere nelle condizioni originali, con i cartellini attaccati.",
    "RETURN ADDRESS": "INDIRIZZO PER I RESI",
    "Working days are Monday to Friday, excluding public holidays.": "I giorni lavorativi vanno dal lunedì al venerdì, esclusi i festivi.",
    "SAYAND pays for return shipping. Contact us to arrange your return shipment.": "SAYAND paga le spese di spedizione del reso. Contattaci per organizzare la spedizione.",
    "Return address unavailable. Please contact support before sending your parcel.": "Indirizzo di reso non disponibile. Contatta l’assistenza prima di spedire il pacco.",
    "Please contact support for returns information.": "Contatta l’assistenza per informazioni sui resi.",
    "Returns & Exchanges | SAYAND": "Resi e cambi | SAYAND",
    "OPEN RETURN QR / LABEL": "APRI QR / ETICHETTA DI RESO",
    "Follow the courier instructions: show the QR code at an eligible drop-off point or during a booked collection. If you received a printable label, print and attach it as instructed.": "Segui le istruzioni del corriere: mostra il QR in un punto abilitato o durante un ritiro prenotato. Se hai ricevuto un’etichetta da stampare, stampala e applicala come indicato.",
    "Request a return and refund? Our team will review your request and provide the courier return instructions.": "Vuoi richiedere un reso e un rimborso? Il nostro team esaminerà la richiesta e fornirà le istruzioni del corriere.",
