    "Press": "Presse",
    "PRESS": "PRESSE",
    "press": "presse",
    "We don't do fashion that makes you choose between who you are and who the world wants you to be. We started this brand to fix a gap we saw everywhere: the space between classic elegance and native authenticity. Too often, modesty was treated as an afterthought. Culture was diluted. Quality was gatekept by price tags. We decided to change that. This is where Nigerian heritage meets global style. We design and curate for everyone who moves through the world with quiet confidence — men, women, and anyone who believes that what you wear should reflect your values. Our pieces span the full spectrum: sharp formalwear, elevated streetwear, timeless classics, and statement accessories that carry the weight of craftsmanship. Everything we make is built to last. Handwoven textiles. Ethically sourced materials. Local production. Top-tier quality at prices that don't require a second thought. We work directly with artisans because we believe the best fashion is human-made, not factory-churned. We're an online store now, shipping globally, with a physical space on the horizon. But no matter how we grow, our promise stays the same: we style you with modesty. Not as a limitation — as a standard. Rooted in culture. Crafted with purpose. Worn with pride.": "Nous ne créons pas une mode qui vous oblige à choisir entre qui vous êtes et qui le monde voudrait que vous soyez.\nNous avons fondé cette marque pour combler un écart que nous constations partout : celui qui sépare l’élégance classique de l’authenticité des origines. Trop souvent, la pudeur était reléguée au second plan. La culture perdait son identité. La qualité était réservée à ceux qui pouvaient en payer le prix. Nous avons décidé de changer les choses.\nC’est ici que l’héritage nigérian rencontre le style international. Nous créons et sélectionnons des pièces pour celles et ceux qui avancent avec une assurance discrète : hommes, femmes et toute personne convaincue que ses vêtements doivent refléter ses valeurs. Nos pièces couvrent tout le vestiaire : tenues habillées impeccables, streetwear raffiné, classiques intemporels et accessoires de caractère qui témoignent du savoir-faire artisanal.\nTout ce que nous réalisons est conçu pour durer. Des textiles tissés à la main. Des matières issues de sources éthiques. Une production locale. Une qualité exceptionnelle à des prix accessibles. Nous travaillons directement avec des artisans, car nous croyons que la meilleure mode naît du travail humain, et non de la production industrielle en série.\nNous sommes aujourd’hui une boutique en ligne qui livre dans le monde entier, avec un espace physique en projet. Mais quelle que soit notre évolution, notre promesse reste la même : vous habiller avec pudeur. Non comme une limite, mais comme une exigence.\nAncrés dans la culture. Créés avec une intention. Portés avec fierté.",
    "Join the SAYAND team. We are always looking for passionate individuals who share our vision for modern, minimalist fashion.": "Rejoignez l’équipe SAYAND. Nous recherchons toujours des personnes passionnées qui partagent notre vision d’une mode moderne et minimaliste.",
