    "Press": "Presse",
    "PRESS": "PRESSE",
    "press": "presse",
    "We don't do fashion that makes you choose between who you are and who the world wants you to be. We started this brand to fix a gap we saw everywhere: the space between classic elegance and native authenticity. Too often, modesty was treated as an afterthought. Culture was diluted. Quality was gatekept by price tags. We decided to change that. This is where Nigerian heritage meets global style. We design and curate for everyone who moves through the world with quiet confidence — men, women, and anyone who believes that what you wear should reflect your values. Our pieces span the full spectrum: sharp formalwear, elevated streetwear, timeless classics, and statement accessories that carry the weight of craftsmanship. Everything we make is built to last. Handwoven textiles. Ethically sourced materials. Local production. Top-tier quality at prices that don't require a second thought. We work directly with artisans because we believe the best fashion is human-made, not factory-churned. We're an online store now, shipping globally, with a physical space on the horizon. But no matter how we grow, our promise stays the same: we style you with modesty. Not as a limitation — as a standard. Rooted in culture. Crafted with purpose. Worn with pride.": "Wir schaffen keine Mode, die Sie vor die Wahl stellt, wer Sie sind und wer Sie nach den Vorstellungen anderer sein sollen.\nWir haben diese Marke gegründet, um eine Lücke zu schließen, die wir überall sahen: die zwischen klassischer Eleganz und der Authentizität der eigenen Wurzeln. Zu oft wurde dezente Kleidung nur als Nebensache betrachtet. Kulturelle Identität wurde verwässert. Qualität blieb denen vorbehalten, die hohe Preise zahlen konnten. Das wollten wir ändern.\nHier trifft nigerianisches Kulturerbe auf internationalen Stil. Wir entwerfen und wählen Stücke für Menschen aus, die mit stiller Selbstsicherheit durchs Leben gehen: Männer, Frauen und alle, die davon überzeugt sind, dass Kleidung die eigenen Werte widerspiegeln sollte. Unser Sortiment umfasst elegante formelle Kleidung, anspruchsvolle Streetwear, zeitlose Klassiker und ausdrucksstarke Accessoires, die handwerkliches Können verkörpern.\nAlles, was wir herstellen, ist auf Langlebigkeit ausgelegt. Handgewebte Textilien. Ethisch beschaffte Materialien. Lokale Produktion. Erstklassige Qualität zu erschwinglichen Preisen. Wir arbeiten direkt mit Kunsthandwerkern zusammen, denn wir glauben, dass die beste Mode von Menschenhand entsteht und nicht aus industrieller Massenfertigung.\nHeute sind wir ein Onlineshop mit weltweitem Versand und einem geplanten Ladengeschäft. Doch egal, wie wir wachsen, unser Versprechen bleibt gleich: Wir kleiden Sie mit dezenter Eleganz. Nicht als Einschränkung, sondern als Maßstab.\nIn der Kultur verwurzelt. Mit Sinn geschaffen. Mit Stolz getragen.",
    "Join the SAYAND team. We are always looking for passionate individuals who share our vision for modern, minimalist fashion.": "Werden Sie Teil des SAYAND-Teams. Wir suchen stets engagierte Menschen, die unsere Vision moderner, minimalistischer Mode teilen.",
