    "Less is": "WENIGER IST",
    "Our design philosophy centers on precision cutting and premium materials. each piece is crafted to transcend seasons, not chase them.": "Unsere Designphilosophie verbindet präzise Schnitte mit hochwertigen Materialien. Jedes Stück soll die Jahreszeiten überdauern, statt Trends zu folgen.",
